
"use client";

import Image from "next/image";
import { portfolioItems, type PortfolioItem } from "@/lib/portfolio-data";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { useState }from "react";
import { PlayCircle } from "lucide-react";
import { cn } from "@/lib/utils";
import dynamic from "next/dynamic";
import { Button } from "@/components/ui/button";

const VideoPlayer = dynamic(() => import("@/components/video-player"), {
  ssr: false,
});


export default function WorkPage() {
  const [selectedItem, setSelectedItem] = useState<PortfolioItem | null>(null);
  const [visibleItems, setVisibleItems] = useState(6);

  const showMoreItems = () => {
    setVisibleItems((prevVisibleItems) => prevVisibleItems + 6);
  };

  return (
    <>
      <div className="h-full w-full flex flex-col p-8">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="text-center mb-12">
              <h1 className="text-4xl font-bold tracking-tight">Our Work</h1>
              <p className="mt-2 max-w-2xl mx-auto text-lg text-foreground/70">
                Browse our collection of projects. Click on any item to view details.
              </p>
            </div>
        </div>

        <div className="flex-1 flex flex-col justify-center">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {portfolioItems.slice(0, visibleItems).map((item) => (
                <div
                  key={item.id}
                  className={cn(
                    "group relative cursor-pointer overflow-hidden rounded-xl bg-card/50 backdrop-blur-md transition-all duration-300 hover:scale-[1.02] aspect-square"
                  )}
                  onClick={() => setSelectedItem(item)}
                >
                  <Image
                    src={item.thumbnailUrl}
                    alt={item.title}
                    fill
                    className="object-cover transition-transform duration-300 group-hover:scale-105"
                    data-ai-hint={item.thumbnailHint}
                    sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex flex-col justify-end p-4">
                    <h3 className="font-bold text-white text-lg">{item.title}</h3>
                    <p className="text-white/80 text-sm line-clamp-2">{item.description}</p>
                  </div>
                  {item.type === "video" && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/20 group-hover:bg-black/40 transition-colors">
                      <PlayCircle className="h-16 w-16 text-white/80" />
                    </div>
                  )}
                </div>
              ))}
            </div>

            {visibleItems < portfolioItems.length && (
              <div className="text-center mt-12">
                <Button onClick={showMoreItems} size="lg">
                  Show More
                </Button>
              </div>
            )}
          </div>
        </div>
      </div>

      <Dialog open={!!selectedItem} onOpenChange={(open) => !open && setSelectedItem(null)}>
        <DialogContent className="max-w-4xl w-full bg-card/80 backdrop-blur-xl border-border/50 p-0 overflow-hidden rounded-lg">
          {selectedItem && (
            <div>
              {selectedItem.type === "video" ? (
                <VideoPlayer
                  source={{
                    type: "video",
                    sources: [{ src: selectedItem.sourceUrl }],
                  }}
                />
              ) : (
                <div className="relative aspect-video bg-black/50">
                  <Image src={selectedItem.sourceUrl} alt={selectedItem.title} fill className="object-contain" />
                </div>
              )}
              <div className="p-6">
                <DialogHeader>
                  <DialogTitle className="text-2xl">{selectedItem.title}</DialogTitle>
                  <DialogDescription className="text-base text-foreground/70 mt-2">
                    {selectedItem.description}
                  </DialogDescription>
                </DialogHeader>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
}
